curl -s 'https://api.labs.crossref.org/data/retractionwatch?you@example.com' -o rw.csv
python3 - <<'EOF'
import csv, collections
c = collections.Counter()
for row in csv.DictReader(open('rw.csv', encoding='utf-8-sig')):
    for reason in row['Reason'].split(';'):
        if reason.strip(): c[reason.strip()] += 1
for reason, n in c.most_common(10): print(n, reason)
EOF
